using Microsoft.ML.Data;

namespace ChurnPredictor.Models;

public class ChurnInput
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4)]
    [ColumnName("Churned")]
    public string Churned { get; set; } = string.Empty;
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }

    public float Probability { get; set; }

    public float Score { get; set; }
}

using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.ML.Transforms;
using ChurnPredictor.Models;

namespace ChurnPredictor.Services;

public class ChurnModelService
{
    private readonly ILogger<ChurnModelService> _logger;
    private readonly MLContext _mlContext;
    private PredictionEngine<ChurnInput, ChurnPrediction>? _predictionEngine;

    public ChurnModelService(ILogger<ChurnModelService> logger)
    {
        _logger = logger;
        _mlContext = new MLContext(seed: 42);
    }

    public ITransformer TrainModel()
    {
        var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
        if (!File.Exists(dataPath))
        {
            // Fall back to project-relative path
            dataPath = Path.Combine(Directory.GetCurrentDirectory(), "Data", "customers.csv");
        }

        _logger.LogInformation("Loading data from {Path}", dataPath);

        var dataView = _mlContext.Data.LoadFromTextFile<ChurnInput>(
            dataPath,
            hasHeader: true,
            separatorChar: ',');

        // Map "Yes"/"No" string to boolean Label column
        var inputKeys = new List<string> { "Yes", "No" };
        var outputValues = new List<bool> { true, false };

        var pipeline = _mlContext.Transforms.Conversion.MapValue(
                "Label",
                new Dictionary<string, bool> { ["Yes"] = true, ["No"] = false },
                inputColumnName: "Churned")
            .Append(_mlContext.Transforms.Categorical.OneHotEncoding(
                "RegionEncoded", "Region"))
            .Append(_mlContext.Transforms.Concatenate(
                "Features", "Age", "Income", "PurchaseHistory", "RegionEncoded"))
            .Append(_mlContext.BinaryClassification.Trainers.FastTree());

        var splitData = _mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);

        _logger.LogInformation("Training model...");
        var model = pipeline.Fit(splitData.TrainSet);

        var predictions = model.Transform(splitData.TestSet);
        var metrics = _mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");

        _logger.LogInformation("Model evaluation - AUC: {AUC:F4}, F1: {F1:F4}",
            metrics.AreaUnderRocCurve, metrics.F1Score);

        // Save model
        var modelPath = Path.Combine(Directory.GetCurrentDirectory(), "Data", "churn-model.zip");
        _mlContext.Model.Save(model, splitData.TrainSet.Schema, modelPath);
        _logger.LogInformation("Model saved to {Path}", modelPath);

        return model;
    }

    public string GetModelPath()
    {
        return Path.Combine(Directory.GetCurrentDirectory(), "Data", "churn-model.zip");
    }

    public MLContext GetMLContext() => _mlContext;
}

