 using Microsoft.Extensions.ML;
 using ChurnPredictor.Models;
 using ChurnPredictor.Services;

 var builder = WebApplication.CreateBuilder(args);

 builder.Services.AddSingleton<ChurnModelService>();

 // Train model before building the app
 var loggerFactory = LoggerFactory.Create(b => b.AddConsole());
 var logger = loggerFactory.CreateLogger<ChurnModelService>();
 var modelService = new ChurnModelService(logger);
 modelService.TrainModel();
 var modelPath = modelService.GetModelPath();

 builder.Services.AddPredictionEnginePool<ChurnInput, ChurnPrediction>()
     .FromFile(modelPath);

 var app = builder.Build();

 app.MapGet("/", () => "Hello");

 app.MapPost("/predict", (PredictionEnginePool<ChurnInput, ChurnPrediction> pool, ChurnInput input) =>
 {
     var prediction = pool.Predict(input);
     return Results.Ok(new
     {
         prediction.PredictedLabel,
         prediction.Probability,
         prediction.Score
     });
 });

 app.Run();
